import { readdirSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"
import { defineConfig } from "@rspress/core"

const here = dirname(fileURLToPath(import.meta.url))

/**
 * Committed TypeDoc markdown lives in docs/v<major>.<minor>/ — one folder per
 * minor release line, regenerated by `yarn docs` (pre-commit hook and release
 * pipeline). Scan the directory so a new minor's docs folder automatically
 * joins the site's version dropdown with zero config churn.
 */
const versionKey = (version: string): [number, number] => {
  const [major = 0, minor = 0] = version.slice(1).split(".").map(Number)
  return [major, minor]
}

const versions = readdirSync(join(here, "docs"), { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && /^v\d+\.\d+$/.test(entry.name))
  .map((entry) => entry.name)
  .sort((a, b) => {
    const [aMajor, aMinor] = versionKey(a)
    const [bMajor, bMinor] = versionKey(b)
    return aMajor - bMajor || aMinor - bMinor
  })

export default defineConfig({
  root: "docs",
  outDir: "doc_build",
  title: "@rae-hill/scratch",
  multiVersion: {
    default: versions.at(-1) ?? "v0.1",
    versions: versions.length > 0 ? versions : ["v0.1"],
  },
})
